//! Third-party notices: `THIRD-PARTY-NOTICES.txt` from the repository root
//! (generated by `blinzel-release notices`) is built into the executable,
//! so the setup exe carries it. The menu writes it next to the downloaded
//! updates and opens it in the default text editor.

use windows::Win32::Foundation::HWND;
use windows::Win32::UI::Shell::ShellExecuteW;
use windows::Win32::UI::WindowsAndMessaging::SW_SHOWNORMAL;
use windows::core::{PCWSTR, w};

use crate::platform::wide;
use crate::setup::install::Layout;

pub const TEXT: &str = include_str!("../../../THIRD-PARTY-NOTICES.txt");

/// Writes the notices to the installation's cache folder and opens them.
pub fn show(hwnd: HWND) -> Result<(), String> {
    let layout = Layout::user().ok_or("no %LOCALAPPDATA%")?;
    let path = layout.cache.join("THIRD-PARTY-NOTICES.txt");
    std::fs::create_dir_all(&layout.cache)
        .and_then(|()| std::fs::write(&path, TEXT.lines().collect::<Vec<_>>().join("\r\n")))
        .map_err(|e| format!("{}: {e}", path.display()))?;
    let file = wide(&path);
    let r = unsafe {
        ShellExecuteW(
            Some(hwnd),
            w!("open"),
            PCWSTR(file.as_ptr()),
            PCWSTR::null(),
            PCWSTR::null(),
            SW_SHOWNORMAL,
        )
    };
    // Values above 32 mean success.
    if r.0 as isize > 32 {
        Ok(())
    } else {
        Err(format!("{}: ShellExecute {}", path.display(), r.0 as isize))
    }
}
